const KEY='persona-builder-priority1-v1';
const EMPTY={research:[],observations:[],patterns:[],personas:[],activity:[],settings:{endpoint:'/api/analyze',provider:'OpenAI-compatible',model:'Configured by backend'}};
function clone(x){return JSON.parse(JSON.stringify(x))}
let state=load(),view='dashboard',researchType='all',activeSource=null,pendingDecision=null;
const $=s=>document.querySelector(s),$$=s=>[...document.querySelectorAll(s)];
function load(){try{const x=JSON.parse(localStorage.getItem(KEY));return x?.research?x:clone(EMPTY)}catch{return clone(EMPTY)}}
function save(){localStorage.setItem(KEY,JSON.stringify(state))}function id(p='id'){return `${p}-${crypto.randomUUID()}`}function now(){return new Date().toISOString()}function day(x){return new Intl.DateTimeFormat('en',{day:'numeric',month:'short',year:'numeric'}).format(new Date(x))}function esc(s=''){return String(s).replace(/[&<>'"]/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;',"'":'&#39;','"':'&quot;'}[c]))}function source(i){return state.research.find(x=>x.id===i)}function obs(i){return state.observations.find(x=>x.id===i)}
function empty(title,text,action,label){return `<div class="empty"><b>${esc(title)}</b><p>${esc(text)}</p>${action?`<button class="primary" data-empty="${action}">${esc(label)}</button>`:''}</div>`}
function log(action){state.activity.unshift({id:id('a'),time:now(),action});state.activity=state.activity.slice(0,20)}
function toast(text){$('#toast').textContent=text;$('#toast').classList.add('show');clearTimeout(toast.t);toast.t=setTimeout(()=>$('#toast').classList.remove('show'),2300)}
function show(sel){$(sel).showModal()}function closeDialogs(){$$('dialog[open]').forEach(x=>x.close())}
function go(name){view=name;$$('.view').forEach(x=>x.classList.remove('active'));$(`#${name}View`).classList.add('active');$$('#nav button').forEach(x=>x.classList.toggle('active',x.dataset.view===name));location.hash=name;render()}
function render(){counts();dashboard();research();analysis();personas();settingsNotice()}
function counts(){const pending=state.observations.filter(x=>x.status==='pending').length+state.patterns.filter(x=>x.status==='pending').length,approvedPatterns=state.patterns.filter(x=>x.status==='approved').length,valid=state.personas.filter(x=>x.status==='Validated').length;$('#navResearch').textContent=state.research.length;$('#navSuggestions').textContent=pending;$('#navPersonas').textContent=state.personas.length;$('#metricResearch').textContent=state.research.length;$('#metricPatterns').textContent=approvedPatterns;$('#metricPersonas').textContent=state.personas.length;$('#metricSuggestions').textContent=pending;$('#pendingPill').textContent=`${pending} pending`;$('#personaBreakdown').textContent=`${valid} validated · ${state.personas.length-valid} unvalidated`}
function dashboard(){const recent=state.research.slice().sort((a,b)=>b.imported.localeCompare(a.imported)).slice(0,3);$('#recentResearch').innerHTML=recent.length?recent.map(researchRow).join(''):empty('No research yet','Import a real source to begin.','add','Add research');const suggestions=[...state.patterns.filter(x=>x.status==='pending').map(x=>({t:'Pattern awaiting review',d:x.title})),...state.observations.filter(x=>x.status==='pending').map(x=>({t:'Evidence awaiting review',d:x.text}))].slice(0,4);$('#dashboardSuggestions').innerHTML=suggestions.length?suggestions.map(x=>`<div class="suggestion-row"><b>${esc(x.t)}</b><small>${esc(x.d)}</small></div>`).join(''):empty('No AI suggestions','Suggestions appear only after real research is analysed.');$('#activityList').innerHTML=state.activity.length?state.activity.slice(0,5).map(x=>`<div class="activity-row"><b>${esc(x.action)}</b><small>${day(x.time)}</small></div>`).join(''):'<div class="meta">No activity yet.</div>';$('#dashboardPersonas').innerHTML=state.personas.length?state.personas.slice(0,5).map(personaCard).join(''):empty('No personas yet','Create a proto-persona or approve evidence first.','persona','Create proto-persona');bindDynamic()}
function researchRow(r){return `<article class="research-card"><div class="source-icon">${r.type==='Interview'?'◉':r.type==='Survey'?'▤':r.type==='Facebook Report'?'f':'⌁'}</div><div><div class="card-title">${esc(r.title)}</div><div>${esc((r.content||r.fileName||'No text preview').slice(0,125))}${(r.content||'').length>125?'…':''}</div><div class="meta">${esc(r.type)} · ${esc(r.participantId||'Unknown')} · imported ${day(r.imported)} · ${r.processed?'analysed':'not analysed'}</div></div><div class="card-actions"><span class="status ${r.processed?'approved':'pending'}">${r.processed?'Analysed':'New'}</span><button class="tiny" data-source="${r.id}">View source</button></div></article>`}
function research(){const q=$('#researchSearch').value.toLowerCase(),list=state.research.filter(r=>(researchType==='all'||r.type===researchType)&&JSON.stringify(r).toLowerCase().includes(q));$('#researchList').innerHTML=list.length?list.sort((a,b)=>b.imported.localeCompare(a.imported)).map(researchRow).join(''):empty('No matching research','Import TXT, CSV, PDF metadata or pasted text.','add','Add research');bindDynamic()}
function analysis(){const observations=state.observations.slice().sort((a,b)=>b.created.localeCompare(a.created));$('#observationCount').textContent=observations.length;$('#patternCount').textContent=state.patterns.length;$('#observationList').innerHTML=observations.length?observations.map(o=>{const s=source(o.sourceId);return `<article class="observation-card"><span class="status ${o.status}">${o.status}</span><div class="card-title">${esc(o.dimension)}</div><p>${esc(o.text)}</p><div class="excerpt">“${esc(o.excerpt)}”</div><div class="meta">${esc(o.evidenceType)} · Source: ${esc(s?.title||'Missing source')}</div><div class="review-actions">${o.status==='pending'?`<button class="tiny" data-review-observation="${o.id}" data-result="approved">Approve</button><button class="tiny" data-edit-observation="${o.id}">Edit</button><button class="tiny" data-review-observation="${o.id}" data-result="rejected">Reject</button>`:''}<button class="tiny" data-source="${o.sourceId}">Open source</button></div></article>`}).join(''):empty('No observations','Analyse imported research or add a source-linked manual observation.');$('#patternList').innerHTML=state.patterns.length?state.patterns.map(p=>`<details class="pattern-card" open><summary><span class="status ${p.status}">${p.status}</span><div class="card-title">${esc(p.title)}</div><p>${esc(p.summary)}</p><div class="meta">${p.observationIds.length} observation${p.observationIds.length===1?'':'s'} · ${new Set(p.observationIds.map(i=>obs(i)?.sourceId)).size} independent source(s)</div></summary><div class="evidence-links">${p.observationIds.map(i=>{const o=obs(i);return o?`<button data-source="${o.sourceId}">${esc(o.excerpt)}</button>`:''}).join('')}</div>${p.status==='pending'?`<div class="review-actions"><button class="tiny" data-review-pattern="${p.id}" data-result="approved">Approve</button><button class="tiny" data-edit-pattern="${p.id}">Edit</button><button class="tiny" data-review-pattern="${p.id}" data-result="rejected">Reject</button></div>`:''}${p.status==='approved'?`<div class="review-actions"><button class="tiny" data-pattern-persona="${p.id}">Create / update persona</button></div>`:''}</details>`).join(''):empty('No patterns','Patterns are accepted only when the API returns source-linked observations.');bindDynamic()}
function personaCard(p){const image={Owner:'assets/active-owner.png',Finder:'assets/temporary-finder.png',Spotter:'assets/quick-spotter.png'}[p.role];return `<article class="persona-card" data-persona="${p.id}">${image?`<img src="${image}" alt="Illustrative context, not a research participant">`:`<div class="persona-image">${esc(p.role[0]||'P')}</div>`}<div class="persona-body"><span class="status ${p.status.toLowerCase()}">${esc(p.status)}</span><h3>${esc(p.name)}</h3><p>${esc(p.goal)}</p><div class="persona-foot"><span>${esc(p.role)}</span><span>Version ${p.version}</span></div></div></article>`}
function personas(){$('#personaGrid').innerHTML=state.personas.length?state.personas.map(personaCard).join(''):empty('No personas yet','Start hypothesis-first with an unvalidated proto-persona, or create one from an approved pattern.','persona','Create proto-persona');bindDynamic()}
function settingsNotice(){const configured=state.settings.endpoint&&state.settings.endpoint!=='/api/analyze';$('#aiConfigNotice').className=`notice ${configured?'ok':''}`;$('#aiConfigNotice').innerHTML=configured?`Analysis will call <b>${esc(state.settings.provider)}</b> through <code>${esc(state.settings.endpoint)}</code>. Results still require review.`:'<b>AI backend not configured for this hosted prototype.</b> Import and manual evidence review work now. Set a backend endpoint in Settings; API keys must remain server-side.'}
function bindDynamic(){$$('[data-empty="add"]').forEach(x=>x.onclick=openResearch);$$('[data-empty="persona"]').forEach(x=>x.onclick=()=>openPersonaForm());$$('[data-source]').forEach(x=>x.onclick=()=>openSource(x.dataset.source));$$('[data-persona]').forEach(x=>x.onclick=()=>openPersonaForm(x.dataset.persona));$$('[data-review-observation]').forEach(x=>x.onclick=()=>decision('observation',x.dataset.reviewObservation,x.dataset.result));$$('[data-review-pattern]').forEach(x=>x.onclick=()=>decision('pattern',x.dataset.reviewPattern,x.dataset.result));$$('[data-edit-observation]').forEach(x=>x.onclick=()=>editObservation(x.dataset.editObservation));$$('[data-edit-pattern]').forEach(x=>x.onclick=()=>editPattern(x.dataset.editPattern));$$('[data-pattern-persona]').forEach(x=>x.onclick=()=>personaFromPattern(x.dataset.patternPersona))}
function openResearch(){$('#researchForm').reset();$('#sourceDate').value=new Date().toISOString().slice(0,10);show('#researchDialog')}
async function saveResearch(e){e.preventDefault();const f=$('#sourceFile').files[0];let content=$('#sourceContent').value.trim(),fileData=null;if(f){if(f.size>1500000){toast('File is too large for browser storage (1.5 MB max)');return}if(f.type==='application/pdf'){fileData=await fileToData(f);if(!content)content='PDF attached. Paste an excerpt for browser preview, or use the configured backend for extraction.'}else if(!content)content=await f.text()}if(!content&&!f){toast('Add pasted content or a file');return}const r={id:id('src'),type:$('#sourceType').value,title:$('#sourceTitle').value.trim(),date:$('#sourceDate').value||'Unknown',participantId:$('#participantId').value.trim()||'Unknown',participantRole:$('#participantRole').value,url:$('#sourceUrl').value.trim()||'',content,fileName:f?.name||'',fileType:f?.type||'',fileData,imported:now(),processed:false};state.research.unshift(r);log(`Added research source: ${r.title}`);save();closeDialogs();render();go('research');toast('Original research source saved')}
function fileToData(file){return new Promise((resolve,reject)=>{const r=new FileReader();r.onload=()=>resolve(r.result);r.onerror=reject;r.readAsDataURL(file)})}
function openSource(sid){const r=source(sid);if(!r)return;activeSource=sid;$('#sourceDialogTitle').textContent=r.title;$('#sourceDialogBody').innerHTML=`<div><span class="status ${r.processed?'approved':'pending'}">${r.processed?'Analysed':'Not analysed'}</span><p class="meta">${esc(r.type)} · ${esc(r.participantId)} · role ${esc(r.participantRole)} · ${esc(r.date)}</p>${r.url?`<p><a href="${esc(r.url)}" target="_blank" rel="noreferrer">Open original webpage ↗</a></p>`:''}<div class="source-original">${esc(r.content||'Binary PDF attached; no text preview.')}</div>${r.fileName?`<p class="meta">Attachment: ${esc(r.fileName)}</p>`:''}</div>`;show('#sourceDialog')}
function openObservation(){closeDialogs();$('#observationForm').reset();$('#observationSourceId').value=activeSource;show('#observationDialog')}
function saveObservation(e){e.preventDefault();const o={id:id('obs'),sourceId:$('#observationSourceId').value,dimension:$('#observationDimension').value,text:$('#observationText').value.trim(),excerpt:$('#observationExcerpt').value.trim(),evidenceType:$('#observationEvidenceType').value,status:'pending',origin:'manual',created:now(),reviewNote:''};state.observations.unshift(o);log('Added a source-linked observation for review');save();closeDialogs();render();go('analysis');toast('Observation saved for review')}
function decision(kind,target,result){const item=(kind==='pattern'?state.patterns:state.observations).find(x=>x.id===target);pendingDecision={kind,target,result};$('#confirmTitle').textContent=`${result==='approved'?'Approve':'Reject'} ${kind}`;$('#confirmText').textContent=kind==='pattern'?item.title:item.text;$('#confirmNote').value='';show('#confirmDialog')}
function confirmDecision(){const note=$('#confirmNote').value.trim();if(!note){toast('Add a review note');return}const list=pendingDecision.kind==='pattern'?state.patterns:state.observations,item=list.find(x=>x.id===pendingDecision.target);item.status=pendingDecision.result;item.reviewNote=note;item.reviewed=now();log(`${pendingDecision.result==='approved'?'Approved':'Rejected'} ${pendingDecision.kind}: ${item.title||item.text}`);if(pendingDecision.kind==='observation'&&pendingDecision.result==='approved')groupApprovedObservations();save();closeDialogs();render();toast('Review decision recorded')}
function groupApprovedObservations(){const approved=state.observations.filter(x=>x.status==='approved');for(const o of approved){if(state.patterns.some(p=>p.observationIds.includes(o.id)))continue;state.patterns.unshift({id:id('pat'),title:`${o.dimension}: ${o.text.slice(0,58)}`,summary:o.text,observationIds:[o.id],status:'pending',created:now(),origin:'researcher-reviewed evidence'})}}
function editObservation(oid){const o=obs(oid),text=prompt('Edit interpretation. The source excerpt will remain unchanged.',o.text);if(text?.trim()){o.text=text.trim();o.status='pending';log('Edited an observation interpretation');save();render()}}
function editPattern(pid){const p=state.patterns.find(x=>x.id===pid),text=prompt('Edit pattern title.',p.title);if(text?.trim()){p.title=text.trim();p.status='pending';log('Edited a behavioural pattern');save();render()}}
function personaFromPattern(pid){const p=state.patterns.find(x=>x.id===pid);openPersonaForm(null,p)}
function openPersonaForm(pid=null,pattern=null){closeDialogs();$('#personaForm').reset();$('#personaId').value=pid||'';$('#personaDialogTitle').textContent=pid?'Update persona':'Create proto-persona';$('#personaHistory').innerHTML='';if(pid){const p=state.personas.find(x=>x.id===pid);$('#personaName').value=p.name;$('#personaRole').value=p.role;$('#personaGoal').value=p.goal;$('#personaStatus').value=p.status;$('#personaHistory').innerHTML=`<b>Version history</b><ol>${p.history.map(h=>`<li>Version ${h.version} · ${day(h.changed)} · ${esc(h.origin)}<br>${esc(h.reason)}</li>`).join('')}</ol>`}else if(pattern){$('#personaGoal').value=pattern.summary;$('#personaReason').value=`Created from approved pattern: ${pattern.title}`;$('#personaForm').dataset.pattern=pattern.id}else delete $('#personaForm').dataset.pattern;show('#personaDialog')}
function savePersona(e){e.preventDefault();const pid=$('#personaId').value,patternId=e.target.dataset.pattern||null,record={name:$('#personaName').value.trim(),role:$('#personaRole').value.trim(),goal:$('#personaGoal').value.trim(),status:$('#personaStatus').value},reason=$('#personaReason').value.trim();if(pid){const p=state.personas.find(x=>x.id===pid);p.history.unshift({version:p.version,values:{name:p.name,role:p.role,goal:p.goal,status:p.status},reason,changed:now(),origin:'manual'});Object.assign(p,record,{version:p.version+1,updated:now()});log(`Updated persona: ${p.name}`)}else{state.personas.unshift({id:id('per'),...record,version:1,patternIds:patternId?[patternId]:[],history:[{version:1,values:record,reason,changed:now(),origin:patternId?'approved pattern':'manual hypothesis'}],created:now(),updated:now()});log(`Created persona: ${record.name}`)}save();closeDialogs();render();go('personas');toast('Persona version saved')}
async function analyse(){const pending=state.research.filter(x=>!x.processed);if(!pending.length){toast('No unprocessed research sources');return}const endpoint=state.settings.endpoint;if(!endpoint){toast('Configure an analysis backend in Settings');return}$('#analyseBtn').disabled=true;$('#analyseBtn').textContent='Analysing…';try{const res=await fetch(endpoint,{method:'POST',headers:{'content-type':'application/json'},body:JSON.stringify({project:{name:'Lost & Found Pets',location:'Lisbon, Portugal'},provider:state.settings.provider,model:state.settings.model,sources:pending.map(({fileData,...r})=>r)})});const data=await res.json().catch(()=>({}));if(!res.ok)throw new Error(data.error||`Backend returned ${res.status}`);if(!Array.isArray(data.observations))throw new Error('Backend response did not include observations');for(const raw of data.observations){const s=source(raw.sourceId);if(!s||!raw.excerpt||!s.content.includes(raw.excerpt))continue;state.observations.unshift({id:id('obs'),sourceId:s.id,dimension:raw.dimension||'Unknown',text:raw.text,excerpt:raw.excerpt,evidenceType:raw.evidenceType==='Interpretation'?'Interpretation':'Direct observation',status:'pending',origin:'AI',created:now(),reviewNote:''})}for(const p of data.patterns||[]){const ids=(p.observationIds||[]).filter(i=>state.observations.some(o=>o.id===i));if(ids.length)state.patterns.unshift({id:id('pat'),title:p.title,summary:p.summary,observationIds:ids,status:'pending',created:now(),origin:'AI'})}pending.forEach(x=>x.processed=true);log(`AI analysed ${pending.length} source(s)`);save();render();toast('AI suggestions are ready for human review')}catch(err){toast(`Analysis unavailable: ${err.message}`);$('#aiConfigNotice').className='notice';$('#aiConfigNotice').innerHTML=`<b>Analysis failed honestly—no findings were created.</b> ${esc(err.message)}`}finally{$('#analyseBtn').disabled=false;$('#analyseBtn').textContent='✦ Analyse unprocessed research'}}
function openSettings(){$('#apiEndpoint').value=state.settings.endpoint;$('#apiProvider').value=state.settings.provider;$('#apiModel').value=state.settings.model;show('#settingsDialog')}
function saveSettings(e){e.preventDefault();state.settings={endpoint:$('#apiEndpoint').value.trim(),provider:$('#apiProvider').value.trim()||'Backend provider',model:$('#apiModel').value.trim()||'Backend configured'};save();closeDialogs();render();toast('Backend settings saved')}
$$('#nav button').forEach(x=>x.onclick=()=>go(x.dataset.view));$$('[data-go]').forEach(x=>x.onclick=()=>go(x.dataset.go));$$('.close').forEach(x=>x.onclick=closeDialogs);$('#quickAdd').onclick=$('#addResearchBtn').onclick=openResearch;$('#quickRefresh').onclick=()=>{go('research');toast('Refresh is on-demand. Choose Add Research Data to import a new source.')};$('#newPersonaBtn').onclick=()=>openPersonaForm();$('#settingsBtn').onclick=openSettings;$('#helpBtn').onclick=()=>toast('Start with Research Data → Add Research Data');$('#manualObservationBtn').onclick=openObservation;$('#analyseBtn').onclick=analyse;$('#researchForm').onsubmit=saveResearch;$('#observationForm').onsubmit=saveObservation;$('#personaForm').onsubmit=savePersona;$('#settingsForm').onsubmit=saveSettings;$('#confirmAction').onclick=confirmDecision;$('#researchSearch').oninput=research;$('#globalSearch').oninput=e=>{$('#researchSearch').value=e.target.value;go('research')};$$('#researchTabs button').forEach(x=>x.onclick=()=>{$$('#researchTabs button').forEach(b=>b.classList.remove('active'));x.classList.add('active');researchType=x.dataset.type;research()});window.onhashchange=()=>{const h=location.hash.slice(1);if($(`#${h}View`))go(h)};go(location.hash.slice(1)||'dashboard');
